def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    difference = new - old
    return {
        "value": difference,
        "trace": {
            "old": old,
            "new": new,
            "difference": difference,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
